def name_operands(region,function_address,operation):
    if region=='Action' and function_address==0xDBBD:
        for name,address,_ in STATE_FIELDS:operation=operation.replace('(#'+format(address,'04X')+')','(@ActionClippedPacketRendererState.'+name+')')
        for old,new in (('(#8D5A)','(@ActionPacketRendererState.FaceGate)'),('(#D560)','(@ActionPolygonPreparationState.Mode)'),
            ('(#9BA3)','(@ActionClipIntersectionsState.OutputSize)'),('(#8D2A)','(@ActionLineRasterState.FirstPoint)'),
            ('(#8D2B)','(@ActionLineRasterState.FirstPoint+1)'),('(#8D2C)','(@ActionLineRasterState.SecondPoint)'),
            ('(#8D2D)','(@ActionLineRasterState.SecondPoint+1)'),('(#8D4E)','(@ActionLineRasterState.PixelOpcode)'),
            ('(#DE0F)','(@ActionLineRasterState.MaskOffset)'),('CALL #DFB6','CALL @Action.CheckFaceOrientation.Entry'),
            ('CALL #DDD1','CALL @Action.CombineListedVertexCodes.Entry'),('CALL #C000','CALL @Action.ClipPolygon.Entry'),
            ('CALL #C941','CALL @Action.ClipSingleEdge.Entry'),('CALL #D511','CALL @Action.PreparePolygonFill.Entry'),
            ('CALL NC, #D511','CALL NC, @Action.PreparePolygonFill.Entry'),('CALL #DDF0','CALL @Action.DrawLinearLine.Entry'),
            ('JP #DBBD','JP @Action.RenderClippedRecords.Entry'),('AND #0F','AND @ActionClippedPacketRendererConst.LowNibbleMask'),
            ('AND #F0','AND @ActionVertexCodeConst.InverseMask'),('AND #07','AND @ActionPacketRendererConst.MaterialMask'),
            ('AND #30','AND @ActionPacketRendererConst.LineModeMask'),('BIT 6, (HL)','BIT @ActionPacketRendererConst.AttachBit, (HL)'),
            ('LD DE, #9000','LD DE, @ActionPolygonPreparationState.Vertices'),('LD HL, #9000','LD HL, @ActionPolygonPreparationState.Vertices'),
            ('LD B, #8E','LD B, @ActionPacketRendererConst.PointPage'),('LD IXH, #8E','LD IXH, @ActionPacketRendererConst.PointPage'),
            ('LD DE, #38A9','LD DE, @ActionPacketRendererConst.XorModeWord'),('LD DE, #30A1','LD DE, @ActionPacketRendererConst.AndModeWord'),
            ('LD DE, #38B1','LD DE, @ActionPacketRendererConst.OrModeWord'),('LD A, #18','LD A, @ActionLineRasterConst.ClearOffset'),
            ('LD A, #10','LD A, @ActionLineRasterConst.SetOffset'),('CP #10','CP @ActionPacketRendererConst.OrSelector')):
            operation=operation.replace(old,new)
        for offset,field in ((0,'Second'),(1,'Second + 1'),(2,'First'),(3,'First + 1'),(4,'ClipCode')):
            operation=re.sub(r'\(IX\s*\+\s*#'+format(offset,'02X')+r'\)','(IX + FRenderProjectedPoint.'+field+')',operation)
        for point,address in (('FirstPoint',0xCF0B),('SecondPoint',0xCF1B)):
            for offset,field in ((0,'Second'),(2,'First'),(4,'ClipCode')):
                operation=operation.replace('(#'+format(address+offset,'04X')+')','(@ActionClipPoints.'+point+'.'+field+')')
    return operation


